from sympy import symbols, diff, solve, expand, Rational

x = symbols("x", real=True)

def cubic(c3, c2, c1, c0):
    return c3*x**3 + c2*x**2 + c1*x + c0

def near_sqrt(r, t):
    a = r * r
    L = r + (t - a) / (2 * r)
    print(f"  a = {a}, f(a) = {r}, f'(a) = 1/(2*{r}) = {1 / (2 * r)}")
    print(f"  L({t}) = {r} + ({t - a})/{2 * r} = {L}, about {float(L):.6f}")

def closed(f, a, b):
    cands = [a] + [c for c in sorted(solve(diff(f, x), x)) if a < c < b] + [b]
    values = [expand(f.subs(x, c)) for c in cands]
    print(f"  f' = {diff(f, x)}, candidates {cands}, values {values}")
    for i in range(len(cands)):
        if values[i] == max(values):
            print(f"  max {values[i]} at x = {cands[i]}")
    for i in range(len(cands)):
        if values[i] == min(values):
            print(f"  min {values[i]} at x = {cands[i]}")

def mvt(f, a, b):
    fa, fb = f.subs(x, a), f.subs(x, b)
    slope = (fb - fa) / (b - a)
    cs = [c for c in sorted(solve(diff(f, x) - slope, x)) if a < c < b]
    print(f"  f({a}) = {fa}, f({b}) = {fb}, secant slope {slope}")
    print(f"  f'(x) = {diff(f, x)} = {slope} inside ({a}, {b}) at c = {cs}")

def powers(n, m, a):
    print(f"  at x = {a}: x^{n} - a^{n} and x^{m} - a^{m} are both 0, the form 0/0")
    print(f"  L'Hopital: {n}x^{n - 1} / ({m}x^{m - 1}) at x = {a} is {n * a**(n - 1) / (m * a**(m - 1))}")

def newton(f, t, n):
    fp = diff(f, x)
    for i in range(n):
        new = t - f.subs(x, t) / fp.subs(x, t)
        print(f"  x{i + 1} = {t} - ({f.subs(x, t)})/({fp.subs(x, t)}) = {new}, about {float(new):.6f}")
        t = new

def run(kind, nums):
    if kind == "sqrt":
        near_sqrt(nums[0], nums[1])
    elif kind == "closed":
        closed(cubic(nums[0], nums[1], nums[2], nums[3]), nums[4], nums[5])
    elif kind == "mvt":
        mvt(cubic(nums[0], nums[1], nums[2], nums[3]), nums[4], nums[5])
    elif kind == "powers":
        powers(int(nums[0]), int(nums[1]), nums[2])
    else:
        newton(cubic(nums[0], nums[1], nums[2], nums[3]), nums[4], int(nums[5]))

problems = [("sqrt", ["6", "36.6"]), ("powers", ["6", "2", "2"]), ("newton", ["0", "1", "0", "-7", "3", "2"]),
    ("closed", ["1", "0", "-3", "0", "0", "3"]), ("mvt", ["1", "0", "0", "0", "-2", "2"]), ("sqrt", ["10", "99"]),
    ("closed", ["1", "0", "-3", "0", "2", "4"]), ("mvt", ["0", "1", "0", "0", "1", "5"])]
for i in range(len(problems)):
    kind, nums = problems[i]
    nums = [Rational(v) for v in nums]
    print(f"Problem {i + 1}: {kind} {nums}")
    run(kind, nums)

