from sympy import symbols, diff, solve, expand, simplify, limit, log, sqrt, oo, Rational
import math

x = symbols("x", real=True)

def classify(f):
    d, d2 = diff(f, x), diff(f, x, 2)
    crit = sorted(solve(d, x))
    print(f"  f' = {d}, f'' = {d2}, critical numbers {crit}")
    for c in crit:
        v = d2.subs(x, c)
        if v > 0:
            print(f"  f''({c}) = {v} > 0: local min f({c}) = {f.subs(x, c)}")
        elif v < 0:
            print(f"  f''({c}) = {v} < 0: local max f({c}) = {f.subs(x, c)}")
        else:
            print(f"  f''({c}) = 0 says nothing: f'({c - 1}) = {d.subs(x, c - 1)}, f'({c + 1}) = {d.subs(x, c + 1)}, the same sign, neither")

def roots(k, q):
    f = x**3 - 3*k**2*x + q
    left, right = f.subs(x, -k), f.subs(x, k)
    count = bool(left > 0) + bool(left * right < 0) + bool(right < 0)
    print(f"  f = {f}: critical numbers {-k} and {k}, f({-k}) = {left}, f({k}) = {right}")
    print(f"  at most one root per piece, and the sign changes on {count} of the 3 pieces: {count} real root(s)")

def power(p, q):
    if p == 0 or q == 0:
        print("  the power is 1 for every x, not an indeterminate form: the limit is 1")
        return
    top, bottom = log(1 + p/x), 1 / (q*x)
    ratio = simplify(diff(top, x) / diff(bottom, x))
    print(f"  ln y = {q*x*top} = {top} / ({bottom}), the form 0/0")
    print(f"  L'Hopital: ({diff(top, x)}) / ({diff(bottom, x)}) = {ratio}, which goes to {limit(ratio, x, oo)}")
    print(f"  the limit is e^{p * q}, about {math.exp(p * q):.6f}")

def closest(m, b, p, q):
    D2 = (x - p)**2 + (m*x + b - q)**2
    c = solve(diff(D2, x), x)[0]
    print(f"  D^2 = {D2}, d/dx = {expand(diff(D2, x))} = 0 at x = {c}")
    if D2.subs(x, c) == 0:
        print(f"  D^2 = 0: ({p}, {q}) is on the line itself")
    else:
        print(f"  closest point ({c}, {m*c + b}), D^2 = {D2.subs(x, c)}, distance {sqrt(D2.subs(x, c))}")

def error(c, n, t, dt):
    y, dy = c * t**n, c * n * t**(n - 1) * dt
    print(f"  y = {y}, dy = {c * n}({t})^{n - 1}({dt}) = {dy}, true change {float(c * (t + dt)**n - y):g}")
    print(f"  dy/y = {dy / y} = {float(100 * dy / y):g}%, which is {n} times {float(100 * dt / t):g}%")

def run(kind, nums):
    if kind == "classify":
        classify(nums[0]*x**3 + nums[1]*x**2 + nums[2]*x + nums[3])
    elif kind == "roots":
        roots(nums[0], nums[1])
    elif kind == "power":
        power(nums[0], nums[1])
    elif kind == "closest":
        closest(nums[0], nums[1], nums[2], nums[3])
    else:
        error(nums[0], int(nums[1]), nums[2], nums[3])

problems = [("classify", ["1", "-3", "-9", "5"]), ("roots", ["1", "-1"]), ("power", ["2", "3"]),
    ("closest", ["2", "-1", "5", "3"]), ("error", ["1", "2", "40", "0.5"]), ("classify", ["1", "-3", "3", "0"]),
    ("roots", ["2", "20"]), ("power", ["-1", "1"]), ("closest", ["1", "0", "2", "2"]), ("classify", ["1", "0", "3", "0"])]
for i in range(len(problems)):
    kind, nums = problems[i]
    nums = [Rational(v) for v in nums]
    print(f"Problem {i + 1}: {kind} {nums}")
    run(kind, nums)

