        if V.subs(x, c) > V.subs(x, best):
            best = c
    print(f"  V(x) = x({L} - 2x)({W} - 2x) on [0, {most}], V'(x) = {expand(diff(V, x))}")
    print(f"  candidates {cands}, volumes {[V.subs(x, c) for c in cands]}")
    print(f"  best cut {best}, volume {V.subs(x, best)}, about {float(V.subs(x, best)):.3f}")

def pen(P, a, b):
    print(f"  constraint {a}x + {b}y = {P}, so A(x) = x({P} - {a}x)/{b}, A'(x) = ({P} - {2*a}x)/{b} = 0")
    side = P / (2*a)
    print(f"  x = {side}, y = {(P - a*side) / b}, area {side * (P - a*side) / b}")

def ticket(d, minutes, limit):
    avg = d / (minutes / 60)
    print(f"  average speed {d}/({minutes}/60) = {avg} mph")
    if avg > limit:
        print(f"  by the mean value theorem the speed was exactly {avg} mph at some moment: over the {limit} limit")
    else:
        print(f"  the average is not over the {limit} limit, so the theorem proves nothing")

def temp(T, h):
    cands = [0] + [c for c in sorted(solve(diff(T, t), t)) if 0 < c < h] + [h]
    values = [T.subs(t, c) for c in cands]
    print(f"  T' = {diff(T, t)}, candidates {cands}, temperatures {values}")
    for i in range(len(cands)):
        if values[i] == max(values):
            print(f"  hottest {values[i]} at t = {cands[i]}")
    for i in range(len(cands)):
        if values[i] == min(values):
            print(f"  coolest {values[i]} at t = {cands[i]}")

def compound(P, r, years):
    rt = r / 100 * years
    print(f"  (1 + {float(r / 100):g}/n)^({years}n) goes to e^{float(rt):g} as n grows, a 1 to the infinity limit")
    print(f"  continuously: {P}e^{float(rt):g} = {float(P) * math.exp(rt):.2f}")
    print(f"  the linear estimate e^u = 1 + u: {P}(1 + {float(rt):g}) = {float(P * (1 + rt)):.2f}")

def run(kind, nums):
    if kind == "box":
        box(nums[0], nums[1])
    elif kind == "pen":
        pen(nums[0], nums[1], nums[2])
    elif kind == "ticket":
        ticket(nums[0], nums[1], nums[2])
    elif kind == "temp":
        temp(nums[0]*t**3 + nums[1]*t**2 + nums[2]*t + nums[3], nums[4])
    else:
        compound(nums[0], nums[1], nums[2])

