from sympy import symbols, diff, solve, factor, Rational

x = symbols("x", real=True)

def form(top, bottom, a):
    t, b = top.subs(x, a), bottom.subs(x, a)
    rule = (diff(top, x) / diff(bottom, x)).subs(x, a)
    print(f"  at x = {a}: the top {top} is {t} and the bottom {bottom} is {b}")
    if t == 0 and b == 0:
        print(f"  the form 0/0: L'Hopital gives ({diff(top, x)})/({diff(bottom, x)}) at x = {a}, which is {rule}")
    elif b != 0:
        print(f"  not 0/0, so substitute: the limit is {t / b}, where the trap, L'Hopital anyway, gives {rule}")
    else:
        print(f"  the form {t}/0: no finite limit, a vertical asymptote, where the trap gives {rule}")

def ends(f, a, b):
    inside = [c for c in sorted(solve(diff(f, x), x)) if a < c < b]
    values = [f.subs(x, c) for c in [a] + inside + [b]]
    print(f"  candidates {[a] + inside + [b]}, values {values}: max {max(values)}, min {min(values)}")
    if len(inside) == 0:
        print("  the trap, critical numbers only, has nothing to compare")
    else:
        trap = [f.subs(x, c) for c in inside]
        print(f"  the trap, critical numbers only: max {max(trap)}, min {min(trap)}")

def inflect(f):
    d2 = diff(f, x, 2)
    zeros = sorted(solve(d2, x))
    print(f"  f'' = {factor(d2)}, zero at {zeros}")
    if len(zeros) == 0:
        print("  f'' is never 0: no inflection points")
        return
    cuts = [zeros[0] - 1] + [(zeros[i] + zeros[i + 1]) / 2 for i in range(len(zeros) - 1)] + [zeros[len(zeros) - 1] + 1]
    found = 0
    for i in range(len(zeros)):
        if bool(d2.subs(x, cuts[i]) > 0) != bool(d2.subs(x, cuts[i + 1]) > 0):
            found = found + 1
            print(f"  x = {zeros[i]}: f'' changes sign, an inflection point ({zeros[i]}, {f.subs(x, zeros[i])})")
        else:
            print(f"  x = {zeros[i]}: f'' has the same sign on both sides, not an inflection point")
    print(f"  {found} inflection point(s), where the trap would count {len(zeros)}")

def safe(f, fp, t):
    steps = 0
    while steps < 50:
        if fp(t) == 0:
            print(f"  stopped after {steps} step(s): f'({t}) = 0, a flat tangent")
            return
        new = t - f(t) / fp(t)
        steps = steps + 1
        if abs(new - t) < 1e-10:
            print(f"  converged to {new:.10f} in {steps} steps, check f = {f(new):.1e}")
            return
        t = new
    print(f"  no convergence in 50 steps: last guess {t:.3e}, f there {f(t):.3e}")

def run(kind, nums):
    if kind == "form":
        form(nums[0]*x**2 + nums[1]*x + nums[2], nums[3]*x + nums[4], nums[5])
    elif kind == "ends":
        ends(nums[0]*x**3 + nums[1]*x**2 + nums[2]*x + nums[3], nums[4], nums[5])
    elif kind == "inflect":
        inflect(nums[0]*x**4 + nums[1]*x**3 + nums[2]*x**2 + nums[3]*x + nums[4])
    else:
        c = [float(v) for v in nums]
        safe(lambda t: c[0]*t**3 + c[1]*t**2 + c[2]*t + c[3], lambda t: 3*c[0]*t**2 + 2*c[1]*t + c[2], c[4])

problems = [("form", ["1", "0", "1", "1", "3", "2"]), ("ends", ["1", "-6", "9", "0", "0", "5"]),
