    ("form", ["1", "0", "-4", "1", "-2", "2"]), ("form", ["1", "0", "1", "1", "-2", "2"]), ("inflect", ["1", "0", "-6", "0", "0"]),
    ("ends", ["1", "0", "-3", "0", "2", "4"]), ("safe", ["0", "1", "-6", "9", "4"]), ("safe", ["0", "1", "0", "1", "1"])]
for i in range(len(problems)):
    kind, nums = problems[i]
    nums = [Rational(v) for v in nums]
    print(f"Problem {i + 1}: {kind} {nums}")
    run(kind, nums)

